import numpy as np

def multimodal_fusion(modalities, method='cross_attention'):
    embeddings = [encoder(m) for m in modalities]
    if method == 'concat':
        return np.concatenate(embeddings, axis=-1)
    elif method == 'cross_attention':
        Q, K, V = embeddings[0], embeddings[1], embeddings[1]
        attn = np.exp(Q @ K.T / np.sqrt(K.shape[-1]))
        attn = attn / np.sum(attn, axis=1, keepdims=True)
        return attn @ V
    elif method == 'tensor':
        outer = np.einsum('i,j->ij', embeddings[0], embeddings[1])
        return outer.flatten()
